151		latest := l.LatestCertificate("M-1")
152		review, _ := l.Review("M-1")
153		second.Number = "C-伪造"
154		second.InstrumentID = "M-9"
155		if latest.Number != "C-1" || review.Latest.Number != "C-1" {
156			t.Fatal("整理重复返回结果影响了此前已取得的最近证书或核对结果")
157		}
158	
159		// 按原始内容再次提交仍标记为重复，返回原业务内容和最初录入时间，
160		// 历史中只保留一张。
161		clock.t = mustDate(t, "2026-10-03")
162		third, dup, err := l.AddCertificate(in)
163		if err != nil || !dup {
164			t.Fatalf("整理过返回数据后按原始内容提交仍应标记为重复，err=%v dup=%v", err, dup)
165		}
166		if third.Error != 0.2 || third.Summary != "s" || third.CreatedAt != first.CreatedAt {
167			t.Fatalf("重复提交应返回原业务内容与最初录入时间：%+v", third)
168		}
169		if n := len(l.data.Certificates); n != 1 {
170			t.Fatalf("历史中应只保留一张证书，得到 %d 张", n)
171		}
172	
173		// 同号但内容不同仍报冲突，不因此前整理过返回数据而接受覆盖。
174		different := in
175		different.Error = 0.1
176		if _, _, err := l.AddCertificate(different); !IsConflict(err) {
177			t.Fatalf("同号不同内容仍应报冲突，得到 %v", err)
178		}
179	}
